{
  "description": "The payment response to be passed on to the TPP.\n\nThe structure of this response is aligned to the structure of the response for the CBUAE payment initiation API.\n",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "data"
  ],
  "properties": {
    "data": {
      "type": "object",
      "description": "Required fields are common for all the payments including file payment. Apart from that, paymentTransactionId is required for all payments except file payments",
      "additionalProperties": false,
      "required": [
        "id",
        "status",
        "statusUpdateDateTime",
        "creationDateTime",
        "paymentPurposeCode"
      ],
      "properties": {
        "id": {
          "description": "An API specific unique identification as assigned by the LFI to identify the domestic Payment resource.",
          "type": "string"
        },
        "consentId": {
          "description": "Unique identification assigned by the TPP to identify the consent resource.",
          "type": "string"
        },
        "paymentTransactionId": {
          "description": "This is an end-to-end identifier that is generated by the underlying payment rails when it is sent from an Originating LFI to a Receiving LFI.\nFor IPP transactions, this is the IPP generated identifier.\n\nThis property is not the same as the `transactionId` in the Bank Data Sharing Transactions API.\n\nThe `paymentTransactionId` must be populated if the payment is processed by the LFI, and updated at the Consent Manager Payment Log API using the `patch` operation.\n",
          "type": "string"
        },
        "status": {
          "description": "Specifies the status of the payment information group\n* Pending: Payment initiation or individual transaction included in the payment initiation is pending. Further checks and status update will be performed.\n* Rejected: The payment initiation has been rejected\n* AcceptedSettlementCompleted: Settlement of the Debtor's account has been completed\n* AcceptedCreditSettlementCompleted: When the Creditor account has been credited with the funds of the payment initiated via the TPP\n* AcceptedWithoutPosting:  When the Recipient Bank has accepted the payment but has not applied the credit to the Creditor account yet.\n",
          "type": "string",
          "enum": [
            "Pending",
            "AcceptedSettlementCompleted",
            "AcceptedCreditSettlementCompleted",
            "AcceptedWithoutPosting",
            "Rejected",
            "Received"
          ]
        },
        "statusUpdateDateTime": {
          "description": "Date and time at which the resource status was updated.",
          "type": "string",
          "format": "date-time"
        },
        "rejectReasonCode": {
          "items": {
            "description": "Rejection Reason",
            "type": "object",
            "required": [
              "code",
              "message"
            ],
            "additionalProperties": false,
            "properties": {
              "code": {
                "description": "Rejected Reason Code is a namespaced rejection reason code. The first part of the code is the namespace, which is the name of the organisation or system (e.g., AANI) that is rejecting the payment, and the second part is the specific rejection reason code for the originating organisation or system.\nPayments that are rejected by AANI will have the AANI prefix, followed by the specific ANNI reason code.\n\nThe Payment resouce is updated with the rejection reason code if a Rejected payment is initially created in a Pending state. \nIf the Payment resource is rejected, and no Payment resource is created - a 4xx HTTP status code is returned to the TPP with the appropriate Error Response.\n",
                "type": "string",
                "pattern": "^[A-Za-z]+\\.[A-Za-z0-9]+$"
              },
              "message": {
                "description": "Message",
                "type": "string"
              }
            }
          },
          "type": "array",
          "minItems": 1
        },
        "creationDateTime": {
          "description": "Date and time at which the message was created.",
          "type": "string",
          "format": "date-time"
        },
        "charges": {
          "$ref": "#/components/schemas/AECharges"
        },
        "exchangeRate": {
          "$ref": "#/components/schemas/AEExchangeRateInformation"
        },
        "currencyRequest": {
          "$ref": "#/components/schemas/AECurrencyRequest"
        },
        "instruction": {
          "$ref": "#/components/schemas/AEPaymentInstruction"
        },
        "paymentPurposeCode": {
          "$ref": "#/components/schemas/AEPaymentPurposeCode"
        },
        "debtorReference": {
          "$ref": "#/components/schemas/AEDebtorReference"
        },
        "openFinanceBilling": {
          "$ref": "#/components/schemas/AEServiceInitiationOpenFinancePaymentBillingGet"
        }
      }
    },
    "meta": {
      "$ref": "#/components/schemas/Meta"
    }
  }
}

{
  "description": "List of charges associated with the payment request",
  "type": "array",
  "items": {
    "type": "object",
    "additionalProperties": false,
    "description": "Set of elements used to provide details of a charge for the payment initiation.\n* For Payments, these Charges are on the Debtor.\n",
    "required": [
      "chargeBearer",
      "type",
      "amount"
    ],
    "properties": {
      "chargeBearer": {
        "$ref": "#/components/schemas/AEChargeBearerType1Code"
      },
      "type": {
        "$ref": "#/components/schemas/AEExternalPaymentChargeTypeCode"
      },
      "amount": {
        "$ref": "#/components/schemas/AEActiveCurrencyAmount"
      }
    }
  }
}

{
  "description": "Specifies which party/parties will bear the charges associated with the processing of the payment transaction.",
  "type": "string",
  "enum": [
    "BorneByCreditor",
    "BorneByDebtor",
    "Shared"
  ]
}

{
  "description": "Charge type, in a coded form.",
  "type": "string",
  "enum": [
    "VAT",
    "Fees"
  ]
}

{
  "description": "The Currency and Amount relating to the Payment",
  "type": "object",
  "required": [
    "amount",
    "currency"
  ],
  "properties": {
    "amount": {
      "$ref": "#/components/schemas/AEActiveOrHistoricAmount"
    },
    "currency": {
      "$ref": "#/components/schemas/AEActiveOrHistoricCurrencyCode"
    }
  }
}

{
  "description": "A number of monetary units specified in an active currency where the unit of currency is explicit and compliant with ISO 4217.",
  "type": "string",
  "pattern": "^\\d{1,16}\\.\\d{2}$",
  "example": "100.00"
}

{
  "description": "A 3 character alphabetic code allocated to a currency under an international currency identification scheme, as described in the latest edition of the international standard ISO 4217 'Codes for the representation of currencies and funds'.",
  "type": "string",
  "pattern": "^[A-Z]{3,3}$",
  "example": "AED"
}

{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "unitCurrency",
    "exchangeRate",
    "rateType"
  ],
  "description": "Further detailed information on the exchange rate that has been used in the payment transaction.",
  "properties": {
    "unitCurrency": {
      "description": "Currency in which the rate of exchange is expressed in a currency exchange. In the example 1GBP = xxxCUR, the unit currency is GBP.",
      "type": "string",
      "pattern": "^[A-Z]{3,3}$"
    },
    "exchangeRate": {
      "description": "The factor used for conversion of an amount from one currency to another. This reflects the price at which one currency was bought with another currency.",
      "type": "number"
    },
    "rateType": {
      "description": "Specifies the type used to complete the currency exchange.",
      "type": "string",
      "enum": [
        "Actual",
        "Agreed",
        "Indicative"
      ]
    },
    "contractIdentification": {
      "description": "Unique and unambiguous reference to the foreign exchange contract agreed between the initiating party/creditor and the debtor agent.",
      "type": "string",
      "minLength": 1,
      "maxLength": 256
    },
    "expirationDateTime": {
      "description": "Specified date and time the exchange rate agreement will expire.All dates in the JSON payloads are represented in ISO 8601 date-time format. \nAll date-time fields in responses must include the timezone. An example is below:\n2017-04-05T10:43:07+00:00",
      "type": "string",
      "format": "date-time"
    }
  }
}

{
  "description": "The details of the non-local currency or FX request that has been agreed between the User and the TPP.\nThe requested ChargeBearer and ExchangeRateInformation are included in this object may be overwritten by the LFI in the returned Consent object.\n",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "currencyOfTransfer"
  ],
  "properties": {
    "instructionPriority": {
      "description": "Indicator of the urgency or order of importance that the instructing party would like the instructed party to apply to the processing of the instruction.",
      "type": "string",
      "enum": [
        "Normal",
        "Urgent"
      ]
    },
    "extendedPurpose": {
      "description": "Specifies the purpose of an international payment.",
      "type": "string",
      "minLength": 1,
      "maxLength": 140
    },
    "chargeBearer": {
      "$ref": "#/components/schemas/AEChargeBearerType1Code"
    },
    "currencyOfTransfer": {
      "description": "Specifies the currency of the to be transferred amount, which is different from the currency of the debtor's account.",
      "type": "string",
      "pattern": "^[A-Z]{3,3}$"
    },
    "destinationCountryCode": {
      "description": "Country in which Credit Account is domiciled. Code to identify a country, a dependency, or another area of particular geopolitical interest, on the basis of country names obtained from the United Nations (ISO 3166, Alpha-2 code).",
      "type": "string",
      "pattern": "[A-Z]{2,2}"
    },
    "exchangeRateInformation": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "unitCurrency",
        "rateType"
      ],
      "description": "Provides details on the currency exchange rate and contract.",
      "properties": {
        "unitCurrency": {
          "description": "Currency in which the rate of exchange is expressed in a currency exchange. In the example 1GBP = xxxCUR, the unit currency is GBP.",
          "type": "string",
          "pattern": "^[A-Z]{3,3}$"
        },
        "exchangeRate": {
          "description": "The factor used for conversion of an amount from one currency to another. This reflects the price at which one currency was bought with another currency.",
          "type": "number"
        },
        "rateType": {
          "description": "Specifies the type used to complete the currency exchange.",
          "type": "string",
          "enum": [
            "Actual",
            "Agreed",
            "Indicative"
          ]
        },
        "contractIdentification": {
          "description": "Unique and unambiguous reference to the foreign exchange contract agreed between the initiating party/creditor and the debtor agent.",
          "type": "string",
          "minLength": 1,
          "maxLength": 256
        }
      }
    },
    "fxQuoteId": {
      "$ref": "#/components/schemas/FxQuoteId"
    }
  }
}

{
  "description": "Required where the consent or payment initiation request relates to a previously quoted FX trade. The TPP must provide the `QuoteId` value where a long-lived consent exists, meaning that each payment initiation request will relate to a different `QuoteId` value.",
  "allOf": [
    {
      "$ref": "#/components/schemas/FxServiceInitiation.FxQuoteIdType"
    }
  ]
}

{
  "type": "string",
  "minLength": 1,
  "maxLength": 128,
  "format": "uuid"
}

{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "Amount"
  ],
  "description": "The Initiation payload is sent by the initiating party to the LFI. It is used to request movement of funds from the debtor account to a creditor for a single payment.",
  "properties": {
    "Amount": {
      "$ref": "#/components/schemas/AEActiveCurrencyAmount"
    }
  }
}

{
  "type": "object",
  "required": [
    "Type"
  ],
  "properties": {
    "NumberOfSuccessfulTransactions": {
      "type": "integer",
      "description": "Number of individual transactions successfully executed by the LFI.\nThis is returned by the LFI after the file is fully processed.\n"
    },
    "Type": {
      "enum": [
        "Collection",
        "LargeValueCollection",
        "PushP2P",
        "PullP2P",
        "Me2Me"
      ],
      "description": "The type payment for billing",
      "type": "string"
    },
    "MerchantId": {
      "description": "MerchantId",
      "type": "string",
      "minLength": 8,
      "maxLength": 20
    }
  },
  "description": "Billing parameters specified by the TPP for a payment initiation",
  "additionalProperties": false
}

{
  "description": "Metadata relevant to the resource.",
  "type": "object",
  "additionalProperties": false
}

{
  "description": "Operation failed due to a invalid request parameter",
  "content": {
    "application/json": {
      "schema": {
        "$ref": "#/components/schemas/Error400"
      }
    }
  }
}

{
  "description": "Default error response payload structure for Ozone Connect",
  "type": "object",
  "required": [
    "errorCode",
    "errorMessage"
  ],
  "properties": {
    "errorCode": {
      "description": "Error code identifying the problem that occurred. This may either be one of the prescribed Error Code(s) or a namespaced Error Code where the namespace is the system or organisation that has responded with the error, and the code is the code specific to the system or organisation. organisation or system.\nLFIs should implement error codes based on the prescribed codes or guidance in the standards, with non-specific codes maintained for backward compatibility with version 1.2.",
      "anyOf": [
        {
          "type": "string",
          "enum": [
            "Consent.Invalid",
            "Consent.BusinessRuleViolation",
            "Consent.FailsControlParameters",
            "Consent.InvalidUserIdentifier",
            "JWS.InvalidSignature",
            "JWS.Malformed",
            "JWS.InvalidClaim",
            "JWS.InvalidHeader",
            "JWE.DecryptionError",
            "JWE.InvalidHeader",
            "GenericRecoverableError",
            "GenericError",
            "Event.UnexpectedEvent",
            "Body.InvalidFormat",
            "Resource.InvalidFormat"
          ]
        },
        {
          "type": "string",
          "pattern": "^[A-Za-z]+\\.[A-Za-z0-9]+$"
        },
        {
          "type": "string"
        }
      ]
    },
    "errorMessage": {
      "$ref": "#/components/schemas/ErrorMessage"
    }
  }
}

{
  "description": "Message describing what problem has occurred",
  "type": "string"
}

{
  "description": "Operation failed as access to the requested resource is forbidden",
  "content": {
    "application/json": {
      "schema": {
        "$ref": "#/components/schemas/Error403"
      }
    }
  }
}

{
  "description": "Error code identifying the problem that occurred. The first part of the code is the namespace, which is the name of the organisation or system that is rejecting the payment, and the second part is the specific rejection reason code for the originating organisation or system.\nLFIs should implement error codes based on the prescribed codes or guidance in the standards, with non-specific codes maintained for backward compatibility with version 1.2.",
  "type": "object",
  "required": [
    "errorCode",
    "errorMessage"
  ],
  "properties": {
    "errorCode": {
      "description": "Error code identifying the problem that occurred. This may either be one of the prescribed Error Code(s) or a namespaced Error Code where the namespace is the system or organisation that has responded with the error, and the code is the code specific to the system or organisation.",
